const mageArt=typeof Image==='undefined'?null:new Image();if(mageArt){mageArt.onload=()=>window.dispatchEvent(new Event('emberwake-art-ready'));mageArt.src=new URL('./assets/mage.png',import.meta.url).href;}
import {WIDTH,HEIGHT,terrain} from './world.js';
import {NODES,HEROES} from './engine.js';
const colors={water:'#1f5f8a',deep:'#163f66',shore:'#4f8f7a',grass:'#3f8a4f',light:'#5aa65a',forest:'#2c6a45',sand:'#b8a868',mountain:'#7a6a78',snow:'#e8e0f0',path:'#e0c98a'};
// Per-region battle palettes: sky top, horizon, ridge, ground, ground speckles, pillars, moon.
const SCENES={
 'The Salt Isles':{sky:'#214079',hor:'#efaeb7',ridge:'#586f99',ground:'#b6a979',fleck:['#dfd2a2','#839b93'],pillar:'#66898e',cap:'#b2e7dd',moon:'#fff3bc',stars:'#e8fff4aa'},
 'The Lowlands':{sky:'#2a2a6e',hor:'#c86f8a',ridge:'#3d3a7a',ground:'#3f7a4a',fleck:['#5aa65a','#2e5e3a'],pillar:'#6a5a8a',cap:'#9a88c0',moon:'#ffe6a8',stars:'#fff4c8aa'},
 'The Mothfen':{sky:'#14304a',hor:'#3fa08a',ridge:'#1f4a5a',ground:'#2f5a52',fleck:['#58c0a0','#1e3e3e'],pillar:'#3a6a6a',cap:'#7ad0b8',moon:'#c8fff0',stars:'#d8fff4aa'},
 'The Cinder Peaks':{sky:'#2a1640',hor:'#e0703a',ridge:'#5a2a3a',ground:'#6a3a32',fleck:['#c0603a','#3a1e22'],pillar:'#7a4a4a',cap:'#e8a070',moon:'#ffd08a',stars:'#ffd8b0aa'},
 'The Sunken Sun':{sky:'#3a0e2a',hor:'#ffb030',ridge:'#7a2030',ground:'#7a3020',fleck:['#ffa040','#40140e'],pillar:'#8a3a2a',cap:'#ffcf70',moon:'#fff0b0',stars:'#ffe8a0aa'}};
function random(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
function poly(c,pts,fill){c.fillStyle=fill;c.beginPath();pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill();}
function tree(c,x,y,s=1){c.fillStyle='#192f2d';c.fillRect(x-1,y+1,2,7*s);poly(c,[[x,y-13*s],[x-6*s,y+2*s],[x+6*s,y+2*s]],'#1a3831');poly(c,[[x-1,y-11*s],[x-5*s,y],[x+1,y]],'#406248');c.fillStyle='#638067';c.fillRect(x-1,y-9*s,1,3);}
function mountain(c,x,y,s=1){poly(c,[[x-14*s,y+8*s],[x,y-19*s],[x+18*s,y+8*s]],'#37484c');poly(c,[[x,y-19*s],[x+18*s,y+8*s],[x+4*s,y+4*s]],'#253d45');poly(c,[[x,y-19*s],[x-5*s,y-9*s],[x,y-11*s],[x+5*s,y-7*s]],'#879a91');}
export function drawMap(canvas,state){canvas.width=640;canvas.height=400;const c=canvas.getContext('2d'),g=terrain(NODES);c.imageSmoothingEnabled=false;const palette={'~':'#225f87','^':'#6c607c','.':'#68a969','"':'#36774e',',':'#47998c',':':'#ae6755','=':'#c8af76',B:state.flags.bell?'#c8af76':'#8d627a',M:state.flags.mill?'#c8af76':'#8d627a',S:state.flags.star?'#c8af76':'#8d627a'};for(let y=0;y<HEIGHT;y++)for(let x=0;x<WIDTH;x++){const t=g[y][x];c.fillStyle=palette[t]||'#b8bd82';c.fillRect(x*10,y*10,10,10);c.fillStyle=t==='~'?'#72b4ce55':'#ffffff18';c.fillRect(x*10+2,y*10+((x+y)%5)+2,4,1);if(t==='^'){poly(c,[[x*10,y*10+9],[x*10+5,y*10],[x*10+10,y*10+9]],'#514962');}if(t==='"')tree(c,x*10+5,y*10+7,.4);}const w=state.world;c.strokeStyle='#ffefb5';c.lineWidth=1;c.strokeRect(w.x*10-1,w.y*10-1,12,12);heroSprite(c,'vera',w.x*10+5,w.y*10+9,.65);}
const masks={
 vera:['.......hh.......','......hhhh......','.....hhhhhh.....','....hhhhhhhh....','...hhhhhhhhhh...','......ss.s......','......ssss......','.......ss.......','.....cccccc.....','....cccccccc....','...cccccccccc...','...cc.cccc.cc...','..s...cccc...s..','......cccc......','.....cccccc.....','....cccccccc....','...cccccccccc...','......dd.dd.....','.....ddd.ddd....'],
 rook:['......mmmm......','.....mmmmmm.....','.....msssms.....','.....mssssm.....','......ssss......','....aaaaaaaa....','...aaaaaaaaaa...','..aaa.aaaa.aaa..','..aaa.aaaa.aaa..','..aaa.aaaa.aaa..','...s..aaaa..s...','......bbbb......','.....aaaaaa.....','.....aa..aa.....','.....aa..aa.....','.....dd..dd.....','....ddd..ddd....'],
 fenn:['......gggg......','.....gggggg.....','....gggggggg....','.....ssssss.....','......ssss......','....gggggggg....','...gggggggggg...','...gggggggggg...','...gg.gggg.gg...','...s..gggg..s...','......bbbb......','.....gggggg.....','.....gggggg.....','.....dd..dd.....','....ddd..ddd....']};
export function heroSprite(c,id,x,y,scale=2){if(id==='vera'&&mageArt?.complete&&mageArt.naturalWidth){const h=24*scale,w=h*mageArt.naturalWidth/mageArt.naturalHeight;c.drawImage(mageArt,x-w/2,y-h,w,h);return;}const mask=masks[id]||masks.vera,p={h:'#5d969d',s:'#e4b58c',c:HEROES.vera.color,d:'#283b4a',m:'#91a5ae',a:'#b0a5a0',b:'#865e45',g:HEROES.fenn.color};c.save();mask.forEach((row,yy)=>[...row].forEach((ch,xx)=>{if(p[ch]){c.fillStyle=p[ch];c.fillRect(Math.round(x+(xx-8)*scale),Math.round(y+(yy-mask.length)*scale),scale,scale);}}));if(id==='vera'){c.fillStyle='#a47952';c.fillRect(x+9*scale,y-17*scale,scale,17*scale);c.fillStyle='#f5c978';c.fillRect(x+8*scale,y-18*scale,3*scale,4*scale);c.fillStyle='#fff1b0';c.fillRect(x+9*scale,y-17*scale,scale,2*scale);}if(id==='rook'){c.fillStyle='#80919b';c.fillRect(x-9*scale,y-15*scale,scale*4,scale*9);c.fillStyle='#d3ae7a';c.fillRect(x-8*scale,y-13*scale,scale,scale*4);c.fillStyle='#cbd2ce';c.fillRect(x+9*scale,y-16*scale,scale,scale*13);}c.restore();}
export function portrait(canvas,id){canvas.width=48;canvas.height=52;const c=canvas.getContext('2d');c.fillStyle='#1b2b38';c.fillRect(0,0,48,52);c.fillStyle=HEROES[id].color+'12';c.fillRect(3,3,42,46);heroSprite(c,id,23,49,2);}
function enemySprite(c,e,x,y,s){c.save();c.translate(x,y);c.scale(s,s);const rect=(x,y,w,h,cl)=>{c.fillStyle=cl;c.fillRect(x,y,w,h);};const p=(a,cl)=>poly(c,a,cl);
 if(e.kind==='moth'){p([[-3,-20],[-22,-31],[-29,-15],[-10,-6],[0,-13]],'#8bb5ad');p([[3,-20],[22,-31],[29,-15],[10,-6],[0,-13]],'#73a0a3');p([[-4,-13],[-20,-12],[-15,0],[0,-5]],'#d8a67b');p([[4,-13],[20,-12],[15,0],[0,-5]],'#ae7f69');rect(-3,-23,6,20,'#333b45');rect(-3,-22,2,3,'#f4c57c');rect(2,-22,2,3,'#f4c57c');}
 if(e.kind==='tree'){rect(-7,-29,14,30,'#786f51');p([[-6,-20],[-25,-15],[-20,-33],[-17,-16],[0,-28],[20,-37],[16,-13],[8,-10]],'#687d52');rect(-9,-36,18,15,'#798e5c');rect(-5,-31,3,3,'#d9c88f');rect(3,-31,3,3,'#d9c88f');p([[-6,-3],[-16,2],[-4,0],[4,0],[16,2],[6,-3]],'#8b8358');}
 if(e.kind==='bell'){rect(-10,-53,20,5,'#a48057');rect(-3,-59,6,7,'#d3a665');p([[-11,-47],[11,-47],[16,-10],[23,-4],[23,1],[-23,1],[-23,-4],[-16,-10]],'#b18e5d');p([[-7,-45],[5,-45],[9,-8],[-11,-8]],'#d6b97c');rect(-20,-5,40,5,'#e1c185');rect(-8,-27,5,7,'#202a36');rect(5,-27,5,7,'#202a36');rect(-4,1,8,7,'#b08755');}
 if(e.kind==='ghost'){p([[0,-49],[-14,-40],[-19,-8],[-25,3],[-8,-1],[0,5],[9,-1],[23,4],[16,-15],[12,-40]],'#8795a2');p([[-1,-45],[-9,-36],[-10,-10],[0,0],[8,-12],[6,-38]],'#b0bab1');rect(-8,-35,5,6,'#203340');rect(4,-35,5,6,'#203340');rect(-3,-23,6,5,'#465e6b');}
 if(e.kind==='knight'){rect(-10,-48,20,17,'#798890');rect(-7,-42,14,4,'#20303a');rect(-2,-42,4,3,'#e0ad79');rect(-14,-29,28,23,'#64777f');rect(-9,-26,18,18,'#879494');rect(-10,-5,6,13,'#425562');rect(4,-5,6,13,'#425562');rect(-23,-26,10,24,'#b29b75');rect(20,-40,3,42,'#b6c1b9');rect(16,-12,11,3,'#bd9865');}
 if(e.kind==='mage'){p([[0,-65],[-16,-39],[17,-39]],'#7c7197');rect(-8,-39,16,13,'#bdadab');rect(-5,-35,3,3,'#e9b376');rect(4,-35,3,3,'#e9b376');p([[-10,-27],[10,-27],[23,6],[-22,6]],'#555779');p([[0,-26],[9,-26],[19,4],[2,4]],'#8b7c98');for(let i=0;i<12;i++){rect(-13+(i*7)%28,-22+(i*11)%25,1,2,'#e6c393');}rect(25,-52,2,58,'#aa927a');rect(22,-55,8,8,'#77d6d4');}
 if(e.kind==='sun'){for(let i=0;i<12;i++){const a=i*Math.PI/6;p([[Math.cos(a)*28,Math.sin(a)*28-35],[Math.cos(a+.1)*46,Math.sin(a+.1)*46-35],[Math.cos(a+.2)*28,Math.sin(a+.2)*28-35]],'#cc8558');}p([[-19,-62],[15,-62],[29,-48],[29,-22],[14,-7],[-15,-7],[-30,-23],[-30,-48]],'#e8ae63');p([[-13,-56],[13,-56],[22,-44],[20,-25],[10,-15],[-12,-17],[-23,-30],[-23,-45]],'#f1cd83');rect(-15,-42,8,5,'#5e4140');rect(7,-42,8,5,'#5e4140');rect(-8,-27,16,3,'#8f5945');}
 c.restore();}
export function drawBattle(canvas,s){canvas.width=480;canvas.height=270;const c=canvas.getContext('2d'),b=s.battle,n=NODES.find(n=>n.id===b.node),r=random(232+n.x);const P=SCENES[n.region]||SCENES['The Lowlands'];c.fillStyle=P.sky;c.fillRect(0,0,480,270);const sky=c.createLinearGradient(0,0,0,170);sky.addColorStop(0,P.sky);sky.addColorStop(1,P.hor);c.fillStyle=sky;c.fillRect(0,0,480,210);for(let i=0;i<70;i++){c.fillStyle=P.stars;c.fillRect(r()*480,r()*110,1,1);}c.fillStyle=P.moon;c.fillRect(350,35,19,19);c.fillStyle=P.sky;c.fillRect(345,31,16,18);for(let x=0;x<500;x+=30){const mx=x,my=140+r()*25;poly(c,[[mx-31,my+18],[mx,my-42],[mx+40,my+18]],P.ridge);poly(c,[[mx,my-42],[mx-11,my-20],[mx,my-24],[mx+11,my-15]],P.cap);}c.fillStyle=P.ground;c.fillRect(0,164,480,106);for(let i=0;i<300;i++){c.fillStyle=P.fleck[i%2];c.fillRect(r()*480,170+r()*100,2+r()*6,1);}for(let x=0;x<500;x+=100){c.fillStyle=P.pillar;c.fillRect(x,130,14,40);c.fillStyle=P.cap;c.fillRect(x-3,127,20,5);}b.enemies.forEach((e,i)=>{const x=250+(i-(b.enemies.length-1)/2)*80;c.fillStyle='#0a1b2488';c.beginPath();c.ellipse(x,151,25,6,0,0,Math.PI*2);c.fill();if(e.hp>0)enemySprite(c,e,x,150,e.kind==='sun'?1.1:1);});s.party.forEach((h,i)=>{const x=90+i*85,y=221+(i%2)*3;c.fillStyle='#0a1b2488';c.beginPath();c.ellipse(x,y+2,19,4,0,0,Math.PI*2);c.fill();if(h.hp>0)heroSprite(c,h.id,x,y,2);if(h.id===b.actor){c.fillStyle='#e9ae6d';poly(c,[[x-4,y-48],[x+4,y-48],[x,y-43]],'#e9ae6d');}});}
